[CmdletBinding()]
param(
    [string]$Version,
    [string]$Repo = 'SKYN1K/ProjectYakuza',
    [string]$GhPath = 'gh',
    [string]$PythonPath = 'python',
    [switch]$SkipLocalInstall,
    [string]$ReleaseTag,
    [switch]$ReplaceExistingRelease
)
$ErrorActionPreference = 'Stop'
$root = Split-Path $PSScriptRoot -Parent
$mod = Join-Path $root 'combat/ProjectYakuza'
$versionLine = Get-Content -LiteralPath (Join-Path $mod '42/mod.info') | Where-Object { $_ -match '^version=' }
$installedVersion = $versionLine.Substring(8).Trim()
if (-not $Version) { $Version = $installedVersion }
if ($Version -ne $installedVersion -or $Version -notmatch '^\d+\.\d+\.\d+$') { throw 'Release version must match mod.info.' }
$notes = Join-Path $mod 'docs/RELEASE_NOTES.md'
if (-not (Test-Path -LiteralPath $notes)) { throw 'Release notes are required.' }
$tag = if ($ReleaseTag) { $ReleaseTag } else { 'v' + $Version }
if ($tag -notmatch '^v\d+(?:\.\d+){0,2}$') { throw 'Invalid release tag.' }
if ($ReplaceExistingRelease -and -not $ReleaseTag) { throw 'Replacing an existing release requires an explicit ReleaseTag.' }
Push-Location $root
try {
    & $GhPath release view $tag --repo $Repo *> $null
    $releaseExists = $LASTEXITCODE -eq 0
    if ($releaseExists -and -not $ReplaceExistingRelease) { throw "Release $tag already exists. Use a new version; published tags are not overwritten." }
    if ($ReplaceExistingRelease) {
        if (-not $releaseExists) { throw 'The explicitly selected release does not exist.' }
        $existingReleaseId = (& $GhPath api ("repos/$Repo/releases/tags/$tag") --jq .id).Trim()
        if ($LASTEXITCODE -ne 0) { throw 'Cannot verify the selected release.' }
        $existingTagSha = (& $GhPath api ("repos/$Repo/git/ref/tags/$tag") --jq .object.sha).Trim()
        if ($LASTEXITCODE -ne 0) { throw 'Cannot verify the selected release tag.' }
    }
    & $PythonPath (Join-Path $root 'tools/combat-tests/validate_asset_cleanup.py')
    if ($LASTEXITCODE -ne 0) { throw 'Runtime asset reference/retirement validation failed.' }
    & $PythonPath (Join-Path $root 'tools/combat-tests/validate_release_runtime.py')
    if ($LASTEXITCODE -ne 0) { throw 'Player release profile validation failed.' }
    $dist = Join-Path $root 'dist'
    New-Item -ItemType Directory -Path $dist -Force | Out-Null
    $archive = Join-Path $dist ('ProjectYakuza-B42-v' + $Version + '.zip')

    & $PythonPath (Join-Path $root 'tools/Build-GamePackage.py') --project combat --version $Version --workshop
    if ($LASTEXITCODE -ne 0) { throw 'Runtime-only package or privacy validation failed.' }
    if (-not $SkipLocalInstall) {
        & $PythonPath (Join-Path $root 'tools/Install-CombatUpdate.py') --version $Version
        if ($LASTEXITCODE -ne 0) { throw 'Local install or loadable Workshop-copy verification failed.' }
    }
    & git add -A -- .gitignore .gitattributes README.md docs/WORKSHOP.md combat tools/Publish-CombatRelease.ps1 tools/Build-GamePackage.py tools/Update-ExistingRelease.py tools/Build-ReleaseRuntime.py tools/combat-tests/validate_release_runtime.py tools/combat-tests/test_release_runtime.py tools/combat-tests/RemovedItemLoadProbe.java tools/Install-CombatUpdate.py tools/combat-tests/test_combat_install.py tools/build_mp_visuals.py tools/combat-tests/build_mp_tests.py tools/combat-tests/mp-test-fixture.lua tools/combat-tests/build_style_entry_tests.py tools/combat-tests/style-entry-test-fixture.lua tools/combat-tests/build_extension_api_tests.py tools/combat-tests/extension-api-test-fixture.lua tools/combat-tests/test_style_observer_builder.py tools/combat-tests/build_taunt_tests.py tools/combat-tests/taunt-test-fixture.lua tools/combat-tests/NativeAuraTextureProbe.java tools/combat-tests/validate_extreme_assets.py tools/combat-tests/build_heat_audio_tests.py tools/combat-tests/heat-audio-test-fixture.lua tools/combat-tests/build_heat_shove_tests.py tools/combat-tests/heat-shove-test-fixture.lua tools/combat-tests/build_quickstep_once_tests.py tools/combat-tests/quickstep-once-test-fixture.lua tools/combat-tests/validate_mp_nodes.py tools/combat-tests/MPObserverProbe.java tools/combat-tests/LuaRunner.java tools/combat-tests/README.md tools/combat-tests/build_charged_ui_tests.py tools/combat-tests/charged-ui-test-fixture.lua tools/combat-tests/ChargeAssetProbe.java tools/combat-tests/OutlineProbe.java tools/combat-tests/validate_finisher_reference_assets.py tools/combat-tests/validate_effect_loader_paths.py tools/combat-tests/validate_charge_source_timing.py tools/combat-tests/PunchTrackProbe.java tools/combat-tests/DetachedEffectProbe.java tools/combat-tests/ChargeTrackProbe.java tools/combat-tests/validate_charge_limb_tracks.py tools/combat-tests/build_weapon_tests.py tools/combat-tests/weapon-test-fixture.lua tools/combat-tests/build_weapon_mp_tests.py tools/combat-