    if ($LASTEXITCODE -ne 0) { throw 'git add failed.' }
    & git diff --cached --quiet
    if ($LASTEXITCODE -eq 1) {
        & git commit -m ("Release " + $tag)
        if ($LASTEXITCODE -ne 0) { throw 'git commit failed.' }
    } elseif ($LASTEXITCODE -ne 0) { throw 'Cannot inspect staged changes.' }
    & git branch -M main
    & git push -u origin main
    if ($LASTEXITCODE -ne 0) { throw 'git push failed.' }
    $revision = (& git rev-parse HEAD).Trim()
    if ($ReplaceExistingRelease) {
        & $PythonPath (Join-Path $root 'tools/Update-ExistingRelease.py') --gh $GhPath --repo $Repo --tag $tag --commit $revision --expected-release-id $existingReleaseId --expected-tag-sha $existingTagSha --notes $notes --archive $archive --archive (Join-Path $dist ('ProjectYakuza-Workshop-v' + $Version + '.zip'))
        if ($LASTEXITCODE -ne 0) { throw 'Explicit release correction failed; source, backups and ZIPs are preserved.' }
    } else {
        & $GhPath release create $tag $archive (Join-Path $dist ('ProjectYakuza-Workshop-v' + $Version + '.zip')) --repo $Repo --target $revision --title $tag --notes-file $notes
        if ($LASTEXITCODE -ne 0) { throw 'GitHub release creation failed; the pushed commit and ZIP are preserved.' }
    }
    & $GhPath release view $tag --repo $Repo --json url,tagName,assets
    if ($LASTEXITCODE -ne 0) { throw 'Cannot verify published release.' }
} finally { Pop-Location }
